// Invalid input throws rcli::Error naming the test (R stops with an error in each of these cases).
void error_cases() {
  check::throws([] { t_test(Vec{1.0}); }, "t.test(1): not enough 'x' observations");
  check::throws([] { t_test(Vec{1, 1, 1}); }, "t.test(c(1, 1, 1)): data are essentially constant");
  check::throws([] { t_test(Vec{1, 2}, Vec{3}); }, "t.test(1:2, 3): not enough 'y' observations");
  check::throws([] { t_test(Vec{1, 2, 3}, Vec{1, 2}, O().paired()); }, "t.test paired: lengths differ");
  check::throws([] { t_test(Vec{1, 2, 3}, O().alt("sideways")); }, "t.test: bad alternative");
  check::throws([] { t_test(Vec{1, 2, 3}, O().conf(1.5)); }, "t.test: bad conf.level");
  check::throws([] { t_test(Vec{1, 2, kInf}); }, "t.test(c(1, 2, Inf)): R fails (missing value in the constancy check)");
  check::throws([] { wilcox_test(Vec{}); }, "wilcox.test(numeric(0)): not enough observations");
  check::throws([] { var_test(Vec{1}, Vec{1, 2}); }, "var.test: not enough 'x' observations");
  check::throws([] { cor_test(Vec{1, 2}, Vec{1, 2}); }, "cor.test pearson: not enough finite observations");
  check::throws([] { cor_test(Vec{1, 2, 3}, Vec{1, 2}); }, "cor.test: lengths differ");
  check::throws([] { cor_test(Vec{1, 2, 3}, Vec{1, 2, 3}, O().method("foo")); }, "cor.test: bad method");
  check::throws([] { shapiro_test(Vec{1, 2}); }, "shapiro.test: sample size must be between 3 and 5000");
  check::throws([] { shapiro_test(Vec(5001, 1.0)); }, "shapiro.test: n > 5000");
  check::throws([] { shapiro_test(Vec{2, 2, 2, 2}); }, "shapiro.test: all 'x' values are identical");
  check::throws([] { ks_test(Vec{1, 2}, Dist::binom(3, 0.5)); }, "ks.test: discrete null distribution");
  check::throws([] { chisq_test_gof(Vec{1, -2, 3}, Vec{}); }, "chisq.test: negative counts");
  check::throws([] { chisq_test_gof(Vec{1, 2, 3}, Vec{0.5, 0.5}); }, "chisq.test: p length mismatch");
  check::throws([] { fisher_test(M(1, 3, {1, 2, 3})); }, "fisher.test: needs at least 2 rows and columns");
  check::throws([] { fisher_test(M(2, 2, {1, 2.5, 3, 4})); }, "fisher.test: non-integer counts");
  check::throws([] { fisher_test(M(6, 6, Vec(36, 40.0))); }, "fisher.test: enumeration too large");
  check::throws([] { binom_test(11, 10); }, "binom.test: x > n");
  check::throws([] { binom_test(3, 10, O().p(1.5)); }, "binom.test: p outside [0, 1]");
  check::throws([] { prop_test(Vec{5}, Vec{4}); }, "prop.test: x > n");
  check::throws([] { prop_test(Vec{1, 2}, Vec{4}); }, "prop.test: lengths differ");
}

// Hand-written expectations for corner cases.
void corner_cases() {
  {  // R: wilcox.test(c(0, 0, 0), conf.int = TRUE) -> V = 0, p NaN, interval (NaN, NaN), estimate NaN
    const HtestResult r = wilcox_test(Vec{0, 0, 0}, O().ci());
    check::close(r.statistic, 0.0, 0, "wilcox all zeros: V");
    check::ok(std::isnan(r.p_value) && std::isnan(r.conf_low) && std::isnan(r.conf_high), "wilcox all zeros: NaN");
    check::ok(r.estimates.size() == 1 && std::isnan(r.estimates[0].second), "wilcox all zeros: estimate NaN");
  }
  {  // fisher r x c: the p-value of a table equals the sum over the tables no more probable (here: all tables)
    const HtestResult r = fisher_test(M(2, 3, {1, 1, 1, 1, 1, 1}));
    check::close(r.p_value, 1.0, 1e-14, "fisher.test(matrix(1, 2, 3))$p.value == 1");  // R: 1
  }
  {  // chisq.test(matrix(c(12, 5, 7, 9), 2, byrow = TRUE))$expected, row-major
    const HtestResult r = chisq_test(M(2, 2, {12, 5, 7, 9}));
    check::close(r.expected[1], 17.0 * 14.0 / 33.0, 1e-15, "chisq.test expected[1, 2]");
  }
}

